import{_ as s,o as t,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS G/H (Day 2) - CephFS: forward scrub","description":"","frontmatter":{"title":"CDS G/H (Day 2) - CephFS: forward scrub","date":"2014-06-26T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["CephFS","一致性检查","forward scrub","数据完整性","分布式存储"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_forward_scrub.md","filePath":"posts/2014/CDS_G_H_Day_2_-_CephFS_-_forward_scrub.md","lastUpdated":1780460162000}'),a={name:"posts/2014/CDS_G_H_Day_2_-_CephFS_-_forward_scrub.md"};function i(l,r,c,n,_,u){return t(),o("div",null,[...r[0]||(r[0]=[e("<p><strong>会议纪要</strong></p><p><strong>会议主题</strong>： CephFS文件系统一致性检查系统（forward scrub）方案讨论</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： （此处应列出参会人员名单）</p><p><strong>会议内容</strong>：</p><ul><li><strong>议题背景</strong>： 会议重点讨论了Ceph文件系统一致性检查系统中的forward scrub方案，此方案旨在确保文件系统的数据一致性。该方案分为两部分：forward scrub和反向检查。forward scrub从文件系统的根节点开始，向下检查所有文件和目录的一致性；反向检查则检查所有rados pool中的对象是否与文件系统相关联。</li><li><strong>forward scrub方案细节</strong>： <ul><li>forward scrub将在MJS（Metadata Server）上创建一个独立的scrub线程。</li><li>scrub线程从scrub iode函数开始，维护一个inode栈，记录需要检查的inode。</li><li>scrub node函数将检查inode，如果是文件，则检查其元数据一致性；如果是目录，则检查目录内容与元数据的一致性。</li><li>对于远程inode（硬链接），需要验证其存在性和链接计数正确性。</li><li>scrub过程中，会对inode设置scrub start stamp和scrub start version，记录scrub的开始时间和版本。</li><li>scrub完成后，会标记scrub finish，并记录scrub结束时间和版本。</li></ul></li><li><strong>讨论要点</strong>： <ul><li>如何处理远程inode的链接计数问题。</li><li>是否有必要在内存中设置scrub start stamp和scrub start version。</li><li>是否可以将scrub分为阻塞和非阻塞两种模式。</li><li>是否可以将scrub分为不同的级别，例如快速内存scrub和完整文件scrub。</li></ul></li><li><strong>行动计划</strong>： <ul><li>进一步完善forward scrub方案，包括处理远程inode链接计数问题和scrub级别划分。</li><li>制定详细的技术方案和实施计划。</li><li>在Ceph社区中讨论和评估该方案。</li></ul></li></ul><p><strong>关键词</strong>： CephFS, forward scrub, distributed storage, consistency check, scrub thread, MJS, inode, metadata, rados pool, object, link count, scrub start stamp, scrub start version, scrub finish, block, non-block, scrub level</p>",7)])])}const b=s(a,[["render",i]]);export{p as __pageData,b as default};
